import java.util.ArrayList;
import java.util.List;

/**
 * ============================================================================
 *  DO NOT EDIT THIS FILE. It is how you check your own homework.
 * ============================================================================
 *
 *  Run it, from this folder:
 *      javac *.java
 *      java Verify
 *
 *  There are 26 checks. When all 26 pass, the homework is done.
 *
 *  This is the same shape of harness as the in-class exercise, on a different
 *  domain — a support desk instead of an order system. It is deliberately not
 *  a continuation: if the exercise went badly you can still do this cleanly.
 *
 *  One thing here that the exercise did NOT cover: Ticket holds a List, and a
 *  List is mutable. Two checks below try to reach inside your record from the
 *  outside. See ../examples/RecordAnatomy.java, section 6, if they fail.
 */
public class Verify {

    private static int passed = 0;
    private static final List<String> failures = new ArrayList<>();

    static void check(String name, boolean condition) {
        if (condition) { passed++; System.out.println("  PASS  " + name); }
        else { failures.add(name); System.out.println("  FAIL  " + name); }
    }

    static void checkEquals(String name, Object expected, Object actual) {
        boolean ok = expected == null ? actual == null : expected.equals(actual);
        if (ok) { passed++; System.out.println("  PASS  " + name); }
        else {
            failures.add(name);
            System.out.println("  FAIL  " + name);
            System.out.println("          expected: " + show(expected));
            System.out.println("          actual:   " + show(actual));
            hintOnWhitespace(expected, actual);
        }
    }

    static void checkThrows(String name, Runnable body) {
        try {
            body.run();
            failures.add(name);
            System.out.println("  FAIL  " + name + "  (nothing was thrown)");
        } catch (IllegalArgumentException e) {
            passed++;
            System.out.println("  PASS  " + name);
        } catch (RuntimeException e) {
            failures.add(name);
            System.out.println("  FAIL  " + name
                    + "  (threw " + e.getClass().getSimpleName()
                    + ", expected IllegalArgumentException)");
        }
    }

    static String show(Object o) {
        return o == null ? "null" : "\"" + o.toString()
                .replace("\n", "\\n")
                .replace("\t", "\\t") + "\"";
    }

    static void hintOnWhitespace(Object expected, Object actual) {
        if (!(expected instanceof String e) || !(actual instanceof String a)) return;
        if (e.replaceAll("\\s", "").equals(a.replaceAll("\\s", ""))) {
            System.out.println("          ^ the text is right; only the WHITESPACE differs.");
            System.out.println("            Almost always the closing \"\"\" is in the wrong");
            System.out.println("            column, or there is one \\n too many at the end.");
        }
    }

    public static void main(String[] args) {
        System.out.println();
        System.out.println("Session 2 homework - The support desk");
        System.out.println("=====================================");
        System.out.println();

        part1_record();
        part1_validation();
        part1_defensiveCopy();
        part1_wither();
        part2_sealed();
        part2_routing();
        part3_describe();
        part4_card();
        part5_auditQuery();

        summary();
    }

    // ---------------------------------------------------------------- PART 1

    static void part1_record() {
        System.out.println("Part 1 - Ticket is a record");

        check("Ticket is a record, not a class",
                Ticket.class.isRecord());

        check("Ticket has exactly four components",
                Ticket.class.isRecord() && Ticket.class.getRecordComponents().length == 4);

        var a = new Ticket("SUP-9", "z@example.com", "Same", List.of("x"));
        var b = new Ticket("SUP-9", "z@example.com", "Same", List.of("x"));
        check("two Tickets with the same values are equal",
                a.equals(b));

        System.out.println();
    }

    static void part1_validation() {
        System.out.println("Part 1 - the compact constructor validates and normalises");

        checkThrows("a blank id is rejected",
                () -> new Ticket("  ", "a@b.com", "Summary", List.of()));

        checkThrows("a null requesterEmail is rejected",
                () -> new Ticket("SUP-1", null, "Summary", List.of()));

        checkThrows("a blank summary is rejected",
                () -> new Ticket("SUP-1", "a@b.com", "   ", List.of()));

        var t = new Ticket("  sup-1001 ", "  Alice@Example.COM ", "  Printer broken  ", List.of());
        checkEquals("the id is trimmed and UPPER-cased", "SUP-1001", t.id());
        checkEquals("the email is trimmed and lower-cased", "alice@example.com", t.requesterEmail());
        checkEquals("the summary is trimmed", "Printer broken", t.summary());

        checkEquals("a null tags list becomes an empty list, not a null",
                List.of(), new Ticket("SUP-2", "a@b.com", "S", null).tags());

        System.out.println();
    }

    static void part1_defensiveCopy() {
        System.out.println("Part 1 - the tags list cannot be edited from outside");

        // 1. The caller keeps its own reference to the list it passed in.
        //    If the record stored that same list, this add() reaches inside it.
        var mine = new ArrayList<String>();
        mine.add("account");
        var ticket = new Ticket("SUP-3", "a@b.com", "S", mine);
        mine.add("SNEAKED-IN");

        checkEquals("editing the caller's list does not change the ticket",
                List.of("account"), ticket.tags());

        // 2. And the list handed back by the accessor is not editable either.
        boolean refused;
        try {
            ticket.tags().add("SNEAKED-IN-TOO");
            refused = false;
        } catch (UnsupportedOperationException e) {
            refused = true;
        }
        check("the list returned by tags() refuses add()", refused);

        System.out.println();
    }

    static void part1_wither() {
        System.out.println("Part 1 - withExtraTag returns a NEW Ticket");

        var original = new Ticket("SUP-4", "a@b.com", "S", List.of("account"));
        var tagged = original.withExtraTag("vip");

        checkEquals("the new ticket has both tags",
                List.of("account", "vip"), tagged.tags());

        checkEquals("the original still has one",
                List.of("account"), original.tags());

        System.out.println();
    }

    // ---------------------------------------------------------------- PART 2

    static void part2_sealed() {
        System.out.println("Part 2 - TicketOutcome is a closed set");

        check("TicketOutcome is sealed",
                TicketOutcome.class.isSealed());

        check("it permits exactly three outcomes, and all three are records",
                TicketOutcome.class.isSealed()
                        && TicketOutcome.class.getPermittedSubclasses().length == 3
                        && allRecords(TicketOutcome.class.getPermittedSubclasses()));

        System.out.println();
    }

    static boolean allRecords(Class<?>[] types) {
        for (Class<?> c : types) if (!c.isRecord()) return false;
        return true;
    }

    static void part2_routing() {
        System.out.println("Part 2 - the router applies its rules in order");

        var router = new TicketRouter();

        check("a password ticket is Resolved",
                router.route(new Ticket("SUP-1", "a@b.com",
                        "Cannot reset password", List.of())) instanceof Resolved);

        check("a security-tagged ticket is Escalated",
                router.route(new Ticket("SUP-2", "a@b.com",
                        "Odd login", List.of("security"))) instanceof Escalated);

        check("a spam.example requester is Rejected",
                router.route(new Ticket("SUP-3", "nobody@spam.example",
                        "YOU HAVE WON", List.of())) instanceof Rejected);

        check("anything else is Escalated to tier-2",
                router.route(new Ticket("SUP-4", "a@b.com",
                        "Printer noise", List.of("hardware")))
                        instanceof Escalated e && e.team().equals("tier-2"));

        // Rule ORDER: this one is a password ticket AND tagged security.
        // Rule 1 is tested first, so it must come back Resolved.
        check("the rules are applied in order, not whichever matches",
                router.route(new Ticket("SUP-5", "a@b.com",
                        "Password reset loop", List.of("security"))) instanceof Resolved);

        System.out.println();
    }

    // ---------------------------------------------------------------- PART 3

    static void part3_describe() {
        System.out.println("Part 3 - describe() renders each outcome");

        var f = new TicketFormatter();

        checkEquals("Resolved",
                "Resolved by bot in 2 min",
                f.describe(new Resolved("bot", 2)));

        checkEquals("Escalated",
                "Escalated to security-team: tagged security",
                f.describe(new Escalated("security-team", "tagged security")));

        checkEquals("Rejected",
                "Rejected: Unknown requester domain",
                f.describe(new Rejected("Unknown requester domain")));

        System.out.println();
    }

    // ---------------------------------------------------------------- PART 4

    static void part4_card() {
        System.out.println("Part 4 - the ticket card (ends WITH a newline)");

        var f = new TicketFormatter();
        var ticket = new Ticket("SUP-1001", "alice@example.com",
                "Cannot reset password", List.of("account"));

        String expected =
                  "TICKET SUP-1001\n"
                + "Requester: alice@example.com\n"
                + "Summary:   Cannot reset password\n"
                + "Tags:      [account]\n"
                + "Outcome:   Resolved by bot in 2 min\n";

        checkEquals("the card matches exactly, including indentation",
                expected, f.card(ticket, new Resolved("bot", 2)));

        System.out.println();
    }

    // ---------------------------------------------------------------- PART 5

    static void part5_auditQuery() {
        System.out.println("Part 5 - the SQL audit query (ends WITHOUT a newline)");

        var f = new TicketFormatter();
        var ticket = new Ticket("SUP-1001", "alice@example.com",
                "Cannot reset password", List.of("account"));

        String expected =
                  "SELECT t.id, t.requester_email, t.status\n"
                + "FROM ticket t\n"
                + "WHERE t.id = 'SUP-1001'\n"
                + "ORDER BY t.created_at DESC";

        checkEquals("the query matches exactly, and does NOT end in a newline",
                expected, f.auditQuery(ticket));

        System.out.println();
    }

    // ---------------------------------------------------------------- SUMMARY

    static void summary() {
        int total = passed + failures.size();
        System.out.println("---------------------------------------------------");
        if (failures.isEmpty()) {
            System.out.println("  ALL " + total + " CHECKS PASSED");
            System.out.println();
            System.out.println("  The two you should look back at are the defensive-copy");
            System.out.println("  checks. `final` protected the FIELD; List.copyOf protected");
            System.out.println("  the LIST. A record is only as immutable as its components,");
            System.out.println("  and nothing in the language reminds you of that.");
        } else {
            System.out.println("  " + passed + "/" + total + " passed. Still to fix:");
            for (String f : failures) System.out.println("    - " + f);
        }
        System.out.println("---------------------------------------------------");
        System.out.println();
    }
}
